import { FC } from 'react';

import { Flex, FlexProps } from 'antd';

import { EFilters, useFilters } from 'features/Filters';
import {
	PlannerDay,
	PlannerFilters,
	PlannerMonth,
	PlannerWeek,
	PlannerYear,
	usePlannerDates,
	usePlannerPostsRetrieveQuery,
} from 'features/Planner';
import { OverlayLoader } from 'shared/ui';
import { formatDate } from 'shared/utils';

interface IPlannerProps extends FlexProps {
	isInner?: boolean;
	channelIds?: string[];
}

export const Planner: FC<IPlannerProps> = ({ className, isInner, channelIds, ...props }) => {
	const { getFilterValue, getALLFilterValues } = useFilters();
	const { selectedDate } = usePlannerDates();
	const type = getFilterValue(EFilters.PLANNER_TYPE) || 'day';

	const dateAfter = new Date(selectedDate);
	const dateBefore = new Date(selectedDate);
	dateAfter.setHours(0, 0, 0, 0);
	dateBefore.setHours(0, 0, 0, 0);

	if (type === 'week') {
		dateAfter.setDate(dateAfter.getDate() - (dateAfter.getDay() || 7) + 1);
		dateBefore.setDate(dateBefore.getDate() + (7 - (dateBefore.getDay() || 7)));
	}

	if (type === 'year' || type === 'month') {
		dateAfter.setDate(23);
		dateAfter.setMonth(dateAfter.getMonth() - 1);
		dateBefore.setDate(13);
		dateBefore.setMonth(dateBefore.getMonth() + 1);
	}

	const { data, isFetching } = usePlannerPostsRetrieveQuery({
		[EFilters.PUBLISHED_AT_FROM]: `${formatDate(dateAfter, 'json', 'from')}`,
		[EFilters.PUBLISHED_AT_TO]: `${formatDate(dateBefore, 'json', 'to')}`,
		[EFilters.CHANNEL_IDS]: channelIds || getALLFilterValues(EFilters.CHANNEL_IDS),
	});

	if (!data) return null;

	return (
		<Flex {...props} vertical gap={16} className={className}>
			<PlannerFilters isInner={isInner} />

			<div style={{ position: 'relative' }}>
				{isFetching && <OverlayLoader />}
				{type === 'day' && <PlannerDay posts={data.results} />}
				{type === 'week' && <PlannerWeek posts={data} />}
				{type === 'month' && <PlannerMonth posts={data} />}
				{type === 'year' && <PlannerYear posts={data} />}
			</div>
		</Flex>
	);
};

export default Planner;
