import { FC, HTMLAttributes } from 'react';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import { PlannerPost, PlannerPosts } from 'features/Planner';

import styles from './PlannerWeekLine.module.scss';

interface IPlannerWeekLineProps extends HTMLAttributes<HTMLDivElement> {
	posts: PlannerPost[][];
	time: string;
}

export const PlannerWeekLine: FC<IPlannerWeekLineProps> = ({ className, time, posts, ...props }) => {
	return (
		<Flex {...props} gap={4} justify="space-between" className={cn(styles.plannerWeekLine, className)}>
			<Typography.Text className={styles.time}>{time}</Typography.Text>

			{posts.map((post, index) => (
				<div className={styles.day} key={index}>
					{!!post.length && <PlannerPosts posts={post} vertical />}
					{!post.length && <div className={styles.empty}></div>}
				</div>
			))}
		</Flex>
	);
};
