import { FC, HTMLAttributes } from 'react';

import { Flex } from 'antd';

import { PlannerPost, PlannerPostResponse, PlannerWeekLine } from 'features/Planner';

interface IPlannerWeekProps extends HTMLAttributes<HTMLDivElement> {
	posts: PlannerPostResponse;
}

export const PlannerWeek: FC<IPlannerWeekProps> = ({ className, posts, ...props }) => {
	const postsMap = posts.results.reduce(
		(acc, post) => {
			const time = new Date(post.published_at).toLocaleString('ru-RU', { hour: '2-digit', minute: '2-digit' });
			acc[time] = [...(acc[time] || []), post];
			return acc;
		},
		{} as Record<string, PlannerPost[]>,
	);

	return (
		<Flex {...props} vertical gap={16} className={className}>
			{!!posts.results.length &&
				Object.keys(postsMap)
					.sort()
					.map((time) => {
						const posts: PlannerPost[][] = [[], [], [], [], [], [], []];

						postsMap[time].forEach((post) => {
							const dayNumber = new Date(post.published_at).getDay() || 7;
							posts[dayNumber - 1].push(post);
						});

						return <PlannerWeekLine key={time} time={time} posts={posts} />;
					})}

			{!posts.results.length &&
				['09:00', '11:00', '13:00', '15:00', '17:00', '19:00', '21:00', '23:00'].map((time) => {
					return <PlannerWeekLine key={time} time={time} posts={[[], [], [], [], [], [], []]} />;
				})}
		</Flex>
	);
};
